  let v = ctx.value, t = 0;
  const set = (nv) => {
    v = nv;
    if (key === 'gyro') cap.innerHTML = tr(v ? 'Gyro ON' : 'Gyro OFF');
    else if (key === 'gyroSens') cap.innerHTML = tr('<b>{n}°</b> of device turn = one full turn', { n: Math.round(gyroTurnDeg(v)) });
